INSERT INTO meal_recipes (id, name, description, instructions, servings, calories_per_serving, protein_g, fat_g, carb_g, goal_tags, serving_notes, tips, expert_advice, suggested_combo, created_at, updated_at) VALUES ('recipe-sandwiches-bo-xot-me-rang', 'Sandwiches bò xốt mè rang', 'Sandwich bò mè rang thơm béo, đậm vị cho bữa sáng nhanh', 'Chưa có hướng dẫn chi tiết.', 1, 0, 0, 0, 0, NULL, 'Lấy 1 lát bánh mì sandwiches rồi quết 1 muỗng canh sốt lên trên rồi cho xà lách, cà chua, dưa leo, hành tây, bò rồi 1 lớp xà lách, 1 lớp bánh mì đã quét sốt rồi kẹp lại, cát miếng vừa ăn', 'Kết hợp xốt Mayonnaise Aji-mayo®, xốt mè rang “Aji-xốt” và tôm khô giúp món ăn có thêm vị đậm đà đặc trưng.Chọn thịt lõi vai thì chọn miếng ít gân mỡ để bên ngoài không dai.', '– Món ăn và thực đơn này chủ yếu áp dụng cho người làm công việc trí não như sinh viên học sinh, giáo viên, công viên chức làm việc hành chính, văn phòng, nghiên cứu sinh, những người cần làm việc trí não dài giờ và chỉ thu xếp được ít thời gian để vận động thể lực.– Thành phần của thực đơn có tỉ lệ chất bột đường cao để cung cấp đủ glucose cho hoạt động của tế bào thần kinh. Với những người lao động trí óc nhưng có đường huyết cao, có thể điều chỉnh khẩu phần bằng cách chỉ ăn khoảng 2/3 lượng thực phẩm giàu bột trong các bữa ăn này, và tăng thêm bữa phụ xen giữa các bữa chính bằng một loại thức ăn có tinh bột thô như khoai củ, đậu đỗ, bánh mì đen, ngũ cốc thô nhiều xơ…', NULL, '2026-08-07T22:02:58.523Z', '2026-08-07T22:02:58.523Z');
