INSERT INTO meal_recipes (id, name, description, instructions, servings, calories_per_serving, protein_g, fat_g, carb_g, goal_tags, serving_notes, tips, expert_advice, suggested_combo, created_at, updated_at) VALUES ('recipe-muc-nhung-giam', 'Mực nhúng giấm', 'Mực nhúng giấm dai giòn sần sật với vị chua thanh nhẹ đặc trưng. Công thức đơn giản từ Món Ngon Mỗi Ngày, hoàn hảo cho bữa cơm gia đình hay tiệc nhậu.', 'Chưa có hướng dẫn chi tiết.', 1, 0, 0, 0, 0, NULL, 'Khi ăn ta nấu sôi nước giấm, nhúng mực vào vừa chín, cuốn bánh tráng và rau dưa, chấm nước mắm ngò.', 'Chọn mực có da sáng, không lem, bám chặt vào thịt, thịt mực trong, đầu dính chặt vào thân.Nấu nước giấm sôi già mới nhúng mực để mực nhanh chín, giòn, giữ vị ngọt.', NULL, NULL, '2026-08-07T22:02:58.523Z', '2026-08-07T22:02:58.523Z');
